 h+=`<div class="card flat"><div class="row wrap between"><div class="row wrap"><span class="badge ${r.route.locality=='local'?'b-acc':'b-info'}">${ic(r.route.locality=='local'?'cpu':'cloud')}${r.route.locality=='local'?'Local model':'Cloud model'}</span><b>${esc(r.route.provider_label)}</b><span class="mono">${esc(r.route.model||'no model selected')}</span></div><span class="badge b-neu">${ic('shield')}Local security processing: on</span></div><p class="t-sec" style="margin-top:8px">${esc(r.route.explanation.text)}</p>${r.route.considered.length?`<div class="t-meta" style="margin-top:6px">Considered: ${r.route.considered.map(c=>`${esc(c.provider_label)} (${c.verdict}${c.reason_text?': '+esc(c.reason_text):''})`).join(' · ')}</div>`:''}</div>`;
